/**
 * The `Ability` a cast actually puts on the stack. A permanent card can print "this spell can't
 * be countered" with no `spellAbility` to carry the flag on (Dragonlord Dromoka) — give such a
 * cast a minimal zero-effect stack ability instead, purely so `protectedFromCounter` can see it.
 *
 * A modal spell's mode was chosen at announcement (CR 601.2b), as part of the option offered by
 * `computePriorityOptions` — substitute the chosen mode's `effects` for the ability's own here,
 * so the executor and every downstream consumer (fizzle check, description) never has to know
 * `modes` exists at all.
 */
function addManaCosts(a: ParsedManaCost, b: ParsedManaCost): ParsedManaCost {
  const hybrid = [...(a.hybrid ?? []), ...(b.hybrid ?? [])];
  const phyrexian = [...(a.phyrexian ?? []), ...(b.phyrexian ?? [])];
  return {
    generic: a.generic + b.generic,
    colorless: a.colorless + b.colorless,
    colored: {
      W: a.colored.W + b.colored.W,
      U: a.colored.U + b.colored.U,
      B: a.colored.B + b.colored.B,
      R: a.colored.R + b.colored.R,
      G: a.colored.G + b.colored.G,
    },
    ...((a.x ?? 0) + (b.x ?? 0) > 0 ? { x: (a.x ?? 0) + (b.x ?? 0) } : {}),
    ...(hybrid.length > 0 ? { hybrid } : {}),
    ...(phyrexian.length > 0 ? { phyrexian } : {}),
  };
}
function resolveCastAbility(
  def: CardDefinition,
  selectedModes: number[] | undefined,
  cardName: string,
  maxChoices?: number,
): Ability | null {
  if (def.spellAbility === null) {
    return def.spellCantBeCountered === true
      ? { kind: 'spell', targets: [], effects: [], cantBeCountered: true }
      : null;
  }
  const modes = def.spellAbility.modes;
  if (modes === undefined) return def.spellAbility;
  const indices = selectedModes ?? [0];
  if (indices.length < modes.minChoices || indices.length > (maxChoices ?? modes.maxChoices)) {
    throw new Error(`engine bug: invalid mode count ${indices.length} for ${cardName}`);
  }
  const chosen = indices.map((index) => modes.options[index]);
  if (chosen.some((option) => option === undefined)) {
    throw new Error(`engine bug: invalid modes ${indices.join(',')} for ${cardName}`);
  }
  return { ...def.spellAbility, effects: chosen.flatMap((option) => option?.effects ?? []) };
}

/**
 * Pay a whole activation cost. A source that is itself tapped as a cost must be excluded from
 * the mana plan, so those non-mana costs are paid first. Sacrifice-another costs are different:
 * the player may use the permanent for mana before sacrificing it, and the sacrifice choice is
 * interactive. Paying mana first keeps a legal action from becoming unpayable when the player
 * chooses a mana-producing artifact as the sacrifice.
 */
function* payActivationCosts(
  ctx: GameContext,
  player: EnginePlayerState,
  perm: EnginePermanent,
  costs: readonly AbilityCost[],
  announcedX = 0,
): GameGen<{ stationPower?: number }> {
  const mana = manaPortionOf(costs);
  const paysManaBeforeSacrifice = costs.some((cost) => cost.kind === 'sacrificeOther');
  const payMana = function* (): GameGen<void> {
    if (totalPips(mana) > 0) {
      // The purpose must match the one `computePriorityOptions` used to decide affordability, or
      // restricted mana that made the ability appear payable would not be spendable here.
      const spendsSource = costs.some(
        (cost) => cost.kind === 'tap' || cost.kind === 'sacrificeSelf' || cost.kind === 'exileSelf',
      );
      // Mana is paid before the ability's own sacrifice, so keep what that sacrifice needs away
      // from mana abilities that sacrifice (Illuminor Szeras), as legality priced it.
      const reserved = paysManaBeforeSacrifice
        ? activationSacrificeReservation(ctx, player, perm, costs, mana, announcedX)
        : null;
      yield* payManaCost(
        ctx,
        player,
        mana,
        { kind: 'activateAbility', sourceOracleId: perm.oracleId },
        spendsSource ? [perm.cardId] : [],
        reserved ?? new Set(),
      );
    }
  };
  if (paysManaBeforeSacrifice) yield* payMana();
  const paymentScope = yield* payAbilityCosts(
    ctx,
    player,
    perm,
    costs,
    'tap',
    announcedX,
    (candidate, remaining) =>
      activationManaSources(
        ctx,
        player,
        perm,
        remaining,
        paysManaBeforeSacrifice ? emptyCost() : mana,
        announcedX,
        [perm.cardId, candidate.cardId],
      ) !== null,
  );
  if (!paysManaBeforeSacrifice) {
    yield* payMana();
  }
  return paymentScope;
}

/**
 * Ward (CR 702.21b): "whenever this becomes the target of a spell or ability an opponent
 * controls, counter it unless that player pays `<cost>`".
 *
 * Modeled as a *triggered ability*, not as a targeting restriction, and that is the load-bearing
 * decision. "Unless the controller pays" is a decision, and `isTargetStillLegal` — the function
 * a legality filter would have to live in — is a pure predicate that cannot ask a player
 * anything. As a trigger it also behaves correctly: it goes on the stack above the spell, so
 * the spell is still countered if ward resolves, and other responses can happen in between.
 */
export function queueWardTriggers(
  ctx: GameContext,
  controllerId: PlayerId,
  stackObjectId: ObjectId,
  targets: readonly ObjectId[],
): void {
  for (const targetId of targets) {
    const perm = ctx.state.battlefield.find((p) => p.id === targetId);
    if (perm === undefined) continue;
    // "an opponent controls" — a permanent's own controller never triggers its ward.
    if (perm.controllerId === controllerId) continue;
    const cost = wardCostOf(ctx, perm);
    if (cost === null) continue;
    const costDescription = describeWardCost(cost);

    const copies = 1 + additionalTypedTriggerCopies(ctx, perm);
    for (let copy = 0; copy < copies; copy++) {
      ctx.state.pendingTriggers.push({
        controllerId: perm.controllerId,
        sourceCardId: perm.cardId,
        sourceObjectId: perm.id,
        sourceOracleId: perm.oracleId,
        sourceName: perm.name,
        ability: {
          kind: 'triggered',
          targets: [],
          effects: [{ op: 'counterUnlessPays', cost, stackObjectId }],
          description: `ward—${costDescription}`,
        },
      });
      debug(ctx, 'stack', `ward triggered: ${perm.name} (${costDescription})`);
    }
  }
}

function describeWardCost(cost: WardCost): string {
  return cost.kind === 'mana' ? describeManaCost(cost.cost) : `pay ${cost.amount} life`;
}

/**
 * "Becomes the target of a spell or ability" (Thunderbreak Regent, CR 603.3d) — every
 * permanent named in `targets` just became a target, regardless of whose. `queueTriggersForEvent`
 * itself enforces "an opponent controls" against `sourceControllerId`.
 */
export function queueBecomesTargetedTriggers(
  ctx: GameContext,
  sourceControllerId: PlayerId,
  targets: readonly ObjectId[],
): void {
  const subjects = targets
    .map((id) => ctx.state.battlefield.find((p) => p.id === id))
    .filter((p): p is EnginePermanent => p !== undefined)
    .map((permanent) => ({ permanent, sourceControllerId }));
  queueTriggersForEvent(ctx, 'becomesTargeted', subjects);
}

function validatePlayFromZonePermission(
  ctx: GameContext,
  player: EnginePlayerState,
  card: EngineCardObject,
  zone: 'libraryTop' | 'graveyard',
  chosenBudgetType: string | undefined,
): string | undefined {
  const permission = playFromZonePermission(ctx, player.id, card, zone);
  if (permission === null) throw new Error(`play from ${zone} is not legal`);
  if (permission.budgetTypes === undefined) {
    if (chosenBudgetType !== undefined) throw new Error('unexpected permanent-type budget choice');
    return undefined;
  }
  if (chosenBudgetType === undefined || !permission.budgetTypes.includes(chosenBudgetType)) {
    throw new Error('permanent-type play budget is not available');
  }
  return chosenBudgetType;
}

function consumePlayFromZonePermission(
  ctx: GameContext,
  player: EnginePlayerState,
  card: EngineCardObject,
  zone: 'libraryTop' | 'graveyard',
  chosenBudgetType: string | undefined,
): void {
  const budgetType = validatePlayFromZonePermission(ctx, player, card, zone, chosenBudgetType);
  if (budgetType !== undefined) {
    player.playFromZoneTypeUsesThisTurn[budgetType] =
      (player.playFromZoneTypeUsesThisTurn[budgetType] ?? 0) + 1;
  }
}

/**
 * Apply a non-pass priority action for `player`. Casting puts the spell on the stack
 * (targets chosen at announcement — brief §5.5); the caster retains priority (CR 117.3c).
 */
/** Counted targets are chosen during announcement, before any costs are paid. */
function* chooseCountTargets(
  ctx: GameContext,
  ability: Ability,
  playerId: PlayerId,
  sourceCardId: string,
  ordinaryTargets: readonly ObjectId[],
  activeSlots?: readonly number[],
  /** The spell's or ability source's colors, for protection (CR 702.16). */
  sourceColors?: readonly Color[],
): GameGen<{
  countTargets: Record<number, ObjectId[]>;
  divisionAmounts: Record<ObjectId, number>;
}> {
  const countTargets: Record<number, ObjectId[]> = {};
  const divisionAmounts: Record<ObjectId, number> = {};
  const chosen = new Set<ObjectId>(ordinaryTargets);
  for (const [slot, spec] of ability.targets.entries()) {
    if (spec.count === undefined || (activeSlots !== undefined && !activeSlots.includes(slot)))
      continue;
    const divided = ability.effects.find(
      (effect): effect is Extract<import('../cards/ability').Effect, { op: 'dealDamageDivided' }> =>
        effect.op === 'dealDamageDivided' && effect.targetSlot === slot,
    );
    const total =
      divided === undefined
        ? undefined
        : evaluateValueIn(ctx, divided.total, { controllerId: playerId, sourceCardId });
    const maximum = Math.min(spec.count.max, total ?? Infinity);
    const picked: ObjectId[] = [];
    for (let index = 0; index < maximum; index++) {
      const candidates = withinTotalManaValue(
        ctx,
        spec,
        picked,
        computeTargetOptions(
          ctx,
          spec,
          playerId,
          sourceColors,
          undefined,
          ordinaryTargets,
          sourceCardId,
        ).filter((id) => !chosen.has(id)),
      );
      if (candidates.length === 0) break;
      const canStop = picked.length >= spec.count.min;
      const outcome = yield {
        decisionType: 'general',
        player: playerId,
        prompt: `Choose target ${picked.length + 1} for ${ability.description ?? 'ability'}`,
        options: [
          ...candidates.map((id) => ({
            type: 'pickTarget',
            description: `Target ${ctx.state.battlefield.find((p) => p.id === id)?.name ?? id}`,
          })),
          ...(canStop ? [{ type: 'decline', description: 'Choose no more targets' }] : []),
        ],
      };
      if (outcome.index >= candidates.length) break;
      const id = candidates[outcome.index] as ObjectId;
      picked.push(id);
      chosen.add(id);
    }
    if (picked.length < spec.count.min) {
      throw new Error(`missing required counted targets for slot ${slot}`);
    }
    countTargets[slot] = picked;
    if (total !== undefined && picked.length > 0) {
      let remaining = total;
      for (const [index, targetId] of picked.entries()) {
        const left = picked.length - index;
        if (left === 1) {
          divisionAmounts[targetId] = remaining;
          break;
        }
        const choices = Array.from({ length: remaining - left + 1 }, (_, n) => n + 1);
        const outcome = yield {
          decisionType: 'general',
          player: playerId,
          prompt: `Assign damage to ${targetId}`,
          options: choices.map((amount) => ({ type: 'assignDamage', description: `${amount}` })),
        };
        const assigned = choices[outcome.index] ?? 1;
        divisionAmounts[targetId] = assigned;
        remaining -= assigned;
      }
    }
  }
  return { countTargets, divisionAmounts };
}

export function* applyPriorityAction(
  ctx: GameContext,
  player: EnginePlayerState,
  payload: PriorityActionPayload,
  outcome: DecisionOutcome,
): GameGen<void> {
  const s = ctx.state;
  switch (payload.kind) {
    case 'pass':
      throw new Error('engine bug: pass is not applied via applyPriorityAction');

    case 'playLand': {
      const sourceZone =
        payload.fromLibraryTop === true
          ? player.library
          : payload.fromGraveyard === true
            ? player.graveyard
            : payload.fromExile === true
              ? ctx.state.exile
              : player.hand;
      const obj = sourceZone.find((o) => o.id === payload.objectId);
      if (obj === undefined) throw new Error('engine bug: land to play not in its source zone');
      if (payload.fromLibraryTop === true) {
        consumePlayFromZonePermission(ctx, player, obj, 'libraryTop', payload.zoneBudgetType);
      }
      if (payload.fromGraveyard === true) {
        consumePlayFromZonePermission(ctx, player, obj, 'graveyard', payload.zoneBudgetType);
      }
      const def = getDefByOracleId(ctx, obj.oracleId, obj.name);
      const mdfc =
        payload.alternativeCast === 'mdfc'
          ? (def.alternativeCasts?.[payload.altIndex ?? 0] ??
            def.alternativeCasts?.find((alt) => alt.kind === 'mdfc'))
          : undefined;
      if (
        payload.alternativeCast === 'mdfc' &&
        (mdfc?.kind !== 'mdfc' || mdfc.landFace === undefined)
      ) {
        throw new Error('missing MDFC land face');
      }
      player.landsPlayedThisTurn += 1;
      emit(
        ctx,
        'playLand',
        { player: player.id, name: mdfc?.landFace?.name ?? obj.name, cardId: obj.cardId },
        player.id,
      );
      debug(ctx, 'legalActions', `${player.id} plays ${mdfc?.landFace?.name ?? obj.name}`);
      yield* moveObject(ctx, obj, {
        zone: 'battlefield',
        controllerId: player.id,
        ...(mdfc?.kind === 'mdfc' ? { face: 'back' as const } : {}),
      });
      return;
    }

    case 'castSpell': {
      const fromZone =
        payload.fromExile === true
          ? s.exile
          : payload.fromLibraryTop === true
            ? player.library
            : payload.fromGraveyard === true
              ? player.graveyard
              : payload.fromCommand
                ? player.commandZone
                : player.hand;
      const obj = fromZone.find((o) => o.id === payload.objectId);
      if (obj === undefined) throw new Error('engine bug: spell to cast not found');
      const def = getDefByOracleId(ctx, obj.oracleId, obj.name);
      let consumeZonePermission: 'libraryTop' | 'graveyard' | undefined;
      if (
        payload.fromGraveyard === true &&
        payload.alternativeCast === undefined &&
        def.castFromGraveyard !== true
      ) {
        validatePlayFromZonePermission(ctx, player, obj, 'graveyard', payload.zoneBudgetType);
        consumeZonePermission = 'graveyard';
      }
      if (payload.fromLibraryTop === true && payload.alternativeCast === undefined) {
        const permission = playFromZonePermission(ctx, player.id, obj, 'libraryTop');
        if (permission !== null) {
          validatePlayFromZonePermission(ctx, player, obj, 'libraryTop', payload.zoneBudgetType);
          consumeZonePermission = 'libraryTop';
        } else if (
          !castFromLibraryTopCandidates(ctx, player.id).some((card) => card.id === obj.id)
        ) {
          throw new Error('cast from library top is not legal');
        }
      }
      let castingAdditionalCosts: AbilityCost[] = [...(def.spellAdditionalCosts ?? [])];
      if (
        payload.fromExile === true &&
        obj.onAdventure !== true &&
        obj.playableUntilEotBy !== player.id
      ) {
        throw new Error('exile cast permission is not legal');
      }
      if (payload.reboundCast === true) {
        throw new Error('rebound cards may be cast only while their delayed trigger resolves');
      }

      const tax = payload.fromCommand ? 2 * (player.commanderCastCount[obj.cardId] ?? 0) : 0;
      const reduction = costReductionFor(ctx, player.id, obj.oracleId, obj.cardId);
      const applyRed = (c: ParsedManaCost): ParsedManaCost => {
        let base = c;
        if (reduction.colored !== undefined) {
          base = subtractColored(base, reduction.colored);
        }
        return subtractGeneric(base, reduction.generic);
      };

      let cost: ParsedManaCost;
      let ability: Ability;
      let targets: ObjectId[];
      let exileOnResolution = false;
      let escaped = false;
      let energyAlternativeCostToPay = 0;
      if (payload.alternativeCast === 'energy') {
        const energyAlternativeCost = s.battlefield
          .filter((perm) => perm.controllerId === player.id)
          .map((perm) => getDefByOracleId(ctx, perm.oracleId, perm.name).energyAlternativeCost)
          .find((amount): amount is number => amount !== undefined);
        if (
          !def.types.some((type) =>
            ['Artifact', 'Battle', 'Creature', 'Enchantment', 'Planeswalker'].includes(type),
          ) ||
          energyAlternativeCost === undefined ||
          player.energy < energyAlternativeCost
        ) {
          throw new Error('energy alternative cost is not legal');
        }
        energyAlternativeCostToPay = energyAlternativeCost;
        cost = emptyCost();
        ability = resolveCastAbility(def, undefined, obj.name) ?? {
          kind: 'spell',
          targets: [],
          effects: [],
        };
        targets = validateChosenTargets(ctx, def, player.id, outcome.targets);
      } else if (payload.alternativeCast === 'commanderFree') {
        if (
          def.commanderFreeCast !== true ||
          payload.fromCommand ||
          !s.battlefield.some((perm) => perm.controllerId === player.id && perm.isCommander)
        ) {
          throw new Error('commander-free alternate cost is not legal');
        }
        cost = emptyCost();
        ability = resolveCastAbility(def, undefined, obj.name) ?? {
          kind: 'spell',
          targets: [],
          effects: [],
        };
        targets = validateChosenTargets(ctx, def, player.id, outcome.targets);
      } else if (payload.alternativeCast === 'nonMana') {
        const alt =
          def.alternativeCasts?.[payload.altIndex ?? 0] ??
          def.alternativeCasts?.find((a) => a.kind === 'nonMana');
        if (alt?.kind !== 'nonMana') throw new Error('missing non-mana alternative cost');
        if (
          (payload.fromGraveyard === true && alt.from !== 'graveyard') ||
          (payload.fromGraveyard !== true && alt.from === 'graveyard')
        ) {
          throw new Error('graveyard alternative cost is not legal from this zone');
        }
        if (
          alt.condition !== undefined &&
          !evaluateCondition(ctx, alt.condition, { cardId: obj.cardId, controllerId: player.id })
        ) {
          throw new Error('non-mana alternative cost condition is not met');
        }
        castingAdditionalCosts = [...castingAdditionalCosts, ...(alt.costs ?? [])];
        // The alternative's own mana cost: {0} for a pitch spell, {B} for Blasphemous Edict.
        cost = alt.manaCost;
        exileOnResolution = alt.exileOnResolution === true;
        escaped = alt.escaped === true;
        ability = resolveCastAbility(def, undefined, obj.name) ?? {
          kind: 'spell',
          targets: [],
          effects: [],
        };
        targets = validateChosenTargets(ctx, def, player.id, outcome.targets);
      } else if (payload.alternativeCast === 'overload') {
        const alt = def.alternativeCasts?.find((a) => a.kind === 'overload');
        if (!alt) throw new Error('missing overload cost');
        cost = alt.manaCost;
        ability = {
          kind: 'spell',
          targets: [],
          effects: [{ op: 'overloadBounceAllNonlandOpponents' }],
        };
        targets = [];
      } else if (payload.alternativeCast === 'adventure' || payload.alternativeCast === 'omen') {
        const alt =
          def.alternativeCasts?.[payload.altIndex ?? 0] ??
          def.alternativeCasts?.find((a) => a.kind === payload.alternativeCast);
        if (!alt) throw new Error(`missing ${payload.alternativeCast} cost`);
        cost = alt.manaCost;
        ability = alt.ability ?? { kind: 'spell', targets: [], effects: [] };
        targets = validateChosenTargets(ctx, def, player.id, outcome.targets);
      } else {
        cost = withX(addGeneric(def.manaCost ?? emptyCost(), tax), payload.x ?? 0);
        const selectedModes =
          payload.modes ?? (payload.mode !== undefined ? [payload.mode] : undefined);
        castingAdditionalCosts = [
          ...castingAdditionalCosts,
          ...modeAdditionalCosts(def, selectedModes),
        ];
        const optional = def.optionalAdditionalCost;
        const optionalCostCount = payload.optionalCostCount ?? 0;
        if (optionalCostCount < 0 || (optional?.repeatable !== true && optionalCostCount > 1)) {
          throw new Error('engine bug: invalid optional additional-cost count');
        }
        if (optionalCostCount > 0 && optional === undefined) {
          throw new Error('engine bug: optional additional cost is not available');
        }
        if (optional !== undefined) {
          for (let i = 0; i < optionalCostCount; i++) {
            castingAdditionalCosts.push({ kind: 'mana', cost: optional.cost });
          }
        }
        ability = resolveCastAbility(
          def,
          payload.modes ?? (payload.mode !== undefined ? [payload.mode] : undefined),
          obj.name,
          maxChoicesFor(ctx, def, { cardId: obj.cardId, controllerId: player.id }),
        ) ?? {
          kind: 'spell',
          targets: [],
          effects: [],
        };
        targets = validateChosenTargets(
          ctx,
          def,
          player.id,
          outcome.targets,
          selectedModeTargetSlots(def, selectedModes),
        );
      }

      const counted = yield* chooseCountTargets(
        ctx,
        ability,
        player.id,
        obj.cardId,
        targets,
        selectedModeTargetSlots(
          def,
          payload.modes ?? (payload.mode !== undefined ? [payload.mode] : undefined),
        ),
        def.colors,
      );
      const allTargets = [...targets, ...Object.values(counted.countTargets).flat()];
      // CR 601.2f: reductions apply once, to the TOTAL — mana cost with X announced plus every
      // additional cost — exactly as `computePriorityOptions` priced the offered action.
      cost = applyRed(addManaCosts(cost, manaPortionOf(castingAdditionalCosts)));
      const targetLifeTax = targetLifeTaxFor(ctx, player.id, allTargets);
      if (player.life < targetLifeTax) {
        throw new Error('engine bug: target life tax became unpayable at application time');
      }
      if (targetLifeTax > 0) loseLife(ctx, player, targetLifeTax);
      if (energyAlternativeCostToPay > 0) {
        player.energy -= energyAlternativeCostToPay;
        emit(
          ctx,
          'energy',
          { amount: -energyAlternativeCostToPay, total: player.energy },
          player.id,
        );
      }
      const manaPayment = yield* payManaCost(ctx, player, cost, {
        kind: 'castSpell',
        oracleId: obj.oracleId,
        isCommander: obj.isCommander,
      });
      if (manaPayment.spellCantBeCountered) ability = { ...ability, cantBeCountered: true };
      yield* paySpellAdditionalCosts(
        ctx,
        player,
        castingAdditionalCosts,
        obj.cardId,
        payload.fromCommand === false &&
          payload.fromLibraryTop !== true &&
          payload.fromExile !== true &&
          payload.fromGraveyard !== true,
        payload.x ?? 0,
      );
      if (consumeZonePermission !== undefined) {
        consumePlayFromZonePermission(
          ctx,
          player,
          obj,
          consumeZonePermission,
          payload.zoneBudgetType,
        );
      }

      if (payload.fromCommand) {
        player.commanderCastCount[obj.cardId] = (player.commanderCastCount[obj.cardId] ?? 0) + 1;
      }

      removeFromCurrentZone(ctx, obj);
      const spellCard: EngineCardObject = {
        ...obj,
        id: `o-${s.nextObjectNum++}` as ObjectId,
        zone: 'stack',
        ...(payload.x !== undefined ? { announcedX: payload.x } : {}),
        ...(def.optionalAdditionalCost !== undefined && (payload.optionalCostCount ?? 0) > 0
          ? {
              optionalCostCounts: {
                [def.optionalAdditionalCost.mechanic]: payload.optionalCostCount ?? 0,
              },
            }
          : {}),
        ...(manaPayment.treasureManaSpent > 0
          ? { treasureManaSpentToCast: manaPayment.treasureManaSpent }
          : {}),
        ...(escaped ? { escaped: true } : {}),
      };
      const spellEntry: EngineStackObject = {
        id: spellCard.id,
        sourceId: spellCard.id,
        controllerId: player.id,
        kind: 'spell',
        description: `${obj.name}`,
        targets,
        ...(Object.keys(counted.countTargets).length > 0
          ? { countTargets: counted.countTargets }
          : {}),
        ...(Object.keys(counted.divisionAmounts).length > 0
          ? { divisionAmounts: counted.divisionAmounts }
          : {}),
        card: spellCard,
        ability,
        sourceOracleId: obj.oracleId,
        sourceCardId: obj.cardId,
        isCommanderCast: payload.fromCommand,
        ...(payload.alternativeCast ? { alternativeCastKind: payload.alternativeCast } : {}),
        ...(payload.x !== undefined ? { announcedX: payload.x } : {}),
        ...(spellCard.optionalCostCounts !== undefined
          ? {
              optionalCostCounts: { ...spellCard.optionalCostCounts },
              ...(spellCard.optionalCostCounts.kicker ? { wasKicked: true, kicked: true } : {}),
            }
          : {}),
        ...(exileOnResolution ? { exileOnResolution: true } : {}),
        ...(escaped ? { escaped: true } : {}),
        ...(payload.fromExile !== true &&
        payload.fromLibraryTop !== true &&
        payload.fromGraveyard !== true &&
        payload.fromCommand !== true &&
        def.keywords.includes('rebound')
          ? { reboundPending: true }
          : {}),
        triggerScope: { manaSpent: manaPayment.manaSpent },
      };
      s.stack.push(spellEntry);
      breakYieldsForStop(ctx, spellEntry);
      emit(
        ctx,
        'castSpell',
        {
          player: player.id,
          name: obj.name,
          cardId: obj.cardId,
          targets,
          fromCommand: payload.fromCommand,
          commanderTax: tax,
        },
        player.id,
      );
      debug(ctx, 'stack', `${player.id} casts ${obj.name}${tax > 0 ? ` (tax {${tax}})` : ''}`, {
        targets,
      });
      // "Whenever you cast a Dragon spell" fires now, with the spell already on the stack below
      // it (CR 603.3b), so the trigger resolves first.
      queueCastTriggers(ctx, spellEntry);
      queueKeywordCastTriggers(ctx, spellEntry);
      queueWardTriggers(ctx, player.id, spellCard.id, allTargets);
      queueBecomesTargetedTriggers(ctx, player.id, allTargets);
      return;
    }

    case 'activateAbility': {
      // Hand-zone activation (CR 112.6a) — cycling and its typed variants. Same short path as
      // the graveyard branch below and for the same reason: the source is a card in a hidden
      // zone with no `EnginePermanent` behind it.
      //
      // `discardSelf` is paid BEFORE the mana, which is what makes cycling behave correctly:
      // the card is in the graveyard while the ability is on the stack (CR 702.29a), so a
      // "whenever you cycle a card" or madness-style observer sees it there, and the card can
      // never be spent twice. `computePriorityOptions` refuses to offer a hand ability with any
      // other non-mana cost, so there is nothing else to pay here.
      if (payload.fromHand === true) {
        const card = player.hand.find((c) => c.id === payload.objectId);
        if (card === undefined) throw new Error('engine bug: hand ability source not in hand');
        const def = getDefByOracleId(ctx, card.oracleId, card.name);
        const activated = def.activatedAbilities[payload.index];
        if (activated === undefined) throw new Error('engine bug: activated ability index invalid');

        // CR 601.2c — targets first, then costs. Same validation as the battlefield path below.
        const targets: ObjectId[] = [];
        for (const [slot, spec] of activated.ability.targets.entries()) {
          if (spec.count !== undefined) continue;
          const choice = outcome.targets.get(slot);
          if (choice === undefined)
            throw new Error(`missing target for slot ${slot} of ${card.name}`);
          if (!computeTargetOptions(ctx, spec, player.id, def.colors).includes(choice)) {
            throw new Error(`illegal target ${choice} for slot ${slot} of ${card.name}`);
          }
          targets.push(choice);
        }

        const counted = yield* chooseCountTargets(
          ctx,
          activated.ability,
          player.id,
          card.cardId,
          targets,
          undefined,
          def.colors,
        );
        const allTargets = [...targets, ...Object.values(counted.countTargets).flat()];

        // The reduced cost, computed exactly as `computePriorityOptions` computed it when it
        // decided this action was affordable — a channel land's own "costs {1} less to activate
        // for each legendary creature you control" is on a card in HAND, which
        // `activationCostReductionFor` cannot see. Read BEFORE the discard, because the card
        // leaving hand must not change what it costs.
        const manaCost = handActivationCost(ctx, def, activated.costs, player.id, card.cardId);

        if (activated.costs.some((c) => c.kind === 'discardSelf')) {
          yield* moveObject(ctx, card, { zone: 'graveyard' });
        }
        if (totalPips(manaCost) > 0) {
          yield* payManaCost(ctx, player, manaCost, {
            kind: 'activateAbility',
            sourceOracleId: card.oracleId,
          });
        }

        const description = activated.ability.description ?? 'activated ability';
        const id = `o-${s.nextObjectNum++}` as ObjectId;
        const stackEntry: EngineStackObject = {
          id,
          sourceId: id,
          controllerId: player.id,
          kind: 'activatedAbility' as const,
          description: `${card.name} — ${description}`,
          targets,
          ...(Object.keys(counted.countTargets).length > 0
            ? { countTargets: counted.countTargets }
            : {}),
          ...(Object.keys(counted.divisionAmounts).length > 0
            ? { divisionAmounts: counted.divisionAmounts }
            : {}),
          card: null,
          ability: activated.ability,
          sourceOracleId: card.oracleId,
          sourceCardId: card.cardId,
          isCommanderCast: false,
        };
        s.stack.push(stackEntry);
        breakYieldsForStop(ctx, stackEntry);
        emit(
          ctx,
          'activateAbility',
          {
            player: player.id,
            source: card.name,
            cardId: card.cardId,
            description,
            targets: allTargets,
          },
          player.id,
        );
        queueWardTriggers(ctx, player.id, id, allTargets);
        queueBecomesTargetedTriggers(ctx, player.id, allTargets);
        debug(ctx, 'stack', `${player.id} activates ${card.name} (hand) — ${description}`);
        return;
      }

      // Graveyard-zone activation (CR 112.6a/602.5c, Runehorn Hellkite) — the source has no
      // `EnginePermanent` (tap/sacrifice/etc. machinery), so it takes its own short path: pay
      // mana directly, pay `exileSelfFromGraveyard` by moving the card, and push a stack entry
      // built from the card's own fields the same way `resolveTopOfStack` builds `source` for
      // any activated ability — it never dereferences a battlefield permanent.
      if (payload.fromGraveyard === true) {
        const card = player.graveyard.find((c) => c.id === payload.objectId);
        if (card === undefined)
          throw new Error('engine bug: graveyard ability source not in graveyard');
        const def = getDefByOracleId(ctx, card.oracleId, card.name);
        const activated = [
          ...def.activatedAbilities,
          ...(ctx.state.temporaryGraveyardAbilities[card.cardId] ?? []),
        ][payload.index];
        if (activated === undefined) throw new Error('engine bug: activated ability index invalid');

        // Every mana component, for the same purpose `computePriorityOptions` priced it with —
        // otherwise mana that may only pay for activations would make an offered action unpayable.
        const manaCost = manaPortionOf(activated.costs);
        if (totalPips(manaCost) > 0) {
          yield* payManaCost(ctx, player, manaCost, {
            kind: 'activateAbility',
            sourceOracleId: card.oracleId,
          });
        }
        if (activated.costs.some((c) => c.kind === 'exileSelfFromGraveyard')) {
          yield* moveObject(ctx, card, { zone: 'exile' });
        }

        const description = activated.ability.description ?? 'activated ability';
        const id = `o-${s.nextObjectNum++}` as ObjectId;
        const stackEntry: EngineStackObject = {
          id,
          sourceId: id,
          controllerId: player.id,
          kind: 'activatedAbility' as const,
          description: `${card.name} — ${description}`,
          targets: [],
          card: null,
          ability: activated.ability,
          sourceOracleId: card.oracleId,
          sourceCardId: card.cardId,
          isCommanderCast: false,
        };
        s.stack.push(stackEntry);
        breakYieldsForStop(ctx, stackEntry);
        emit(
          ctx,
          'activateAbility',
          { player: player.id, source: card.name, cardId: card.cardId, description, targets: [] },
          player.id,
        );
        debug(ctx, 'stack', `${player.id} activates ${card.name} (graveyard) — ${description}`);
        return;
      }

      const perm = ctx.state.battlefield.find((p) => p.id === payload.objectId);
      if (perm === undefined) throw new Error('engine bug: ability source not on the battlefield');
      if (activatingAbilitiesBlockedFor(ctx, player.id, perm)) {
        throw new Error('activated abilities of this permanent are currently forbidden');
      }
      const def = getDefByOracleId(ctx, perm.oracleId, perm.name);
      const activated = (computeCharacteristics(ctx, perm).activatedAbilities ??
        def.activatedAbilities)[payload.index];
      if (activated === undefined) throw new Error('engine bug: activated ability index invalid');
      if (
        activated.condition !== undefined &&
        !evaluateCondition(ctx, activated.condition, {
          cardId: perm.cardId,
          controllerId: player.id,
        })
      ) {
        throw new Error('activated ability condition is not met');
      }
      if (activated.exhaust === true && perm.exhaustedAbilities?.includes(payload.index) === true) {
        throw new Error('this exhaust ability has already been activated');
      }

      // CR 601.2b/602.2b: a modal ability's mode was announced by the option itself, before
      // targets. Fold it in now so the stack entry, fizzle check and executor see only the
      // chosen modes' effects, and only those modes' target slots are announced.
      const modes = activated.ability.modes;
      if ((modes === undefined) !== (payload.modes === undefined)) {
        throw new Error(`engine bug: mode announcement mismatch for ${perm.name}`);
      }
      const selectedModes = payload.modes;
      if (
        modes !== undefined &&
        selectedModes !== undefined &&
        !abilityModeSelections(modes).some(
          (candidate) =>
            candidate.length === selectedModes.length &&
            candidate.every((mode, i) => mode === selectedModes[i]),
        )
      ) {
        throw new Error(`engine bug: invalid modes ${selectedModes.join(',')} for ${perm.name}`);
      }
      const announced =
        selectedModes === undefined
          ? activated.ability
          : abilityForModes(activated.ability, selectedModes);
      const activeSlots =
        modes === undefined || selectedModes === undefined
          ? undefined
          : abilityModeTargetSlots(modes, selectedModes);
      const modeLabel =
        modes === undefined || selectedModes === undefined
          ? undefined
          : abilityModeLabel(modes, selectedModes);

      // CR 601.2c/601.2h: targets are chosen, then costs are paid, then the ability is on the
      // stack. Paying is one indivisible act and happens even if the ability never resolves —
      // which is why sacrificing the source does not remove the ability from the stack.
      // Indexed by slot, so an unchosen mode's slot stays empty (as a modal spell's does).
      const targets: ObjectId[] = [];
      for (const [slot, spec] of activated.ability.targets.entries()) {
        if (spec.count !== undefined || !slotIsActive(activeSlots, slot)) continue;
        const choice = outcome.targets.get(slot);
        if (choice === undefined)
          throw new Error(`missing target for slot ${slot} of ${perm.name}`);
        const legal = computeTargetOptions(
          ctx,
          spec,
          player.id,
          colorsOf(ctx, perm),
          undefined,
          undefined,
          perm.cardId,
        );
        if (!legal.includes(choice)) {
          throw new Error(`illegal target ${choice} for slot ${slot} of ${perm.name}`);
        }
        targets[slot] = choice;
      }

      const counted = yield* chooseCountTargets(
        ctx,
        announced,
        player.id,
        perm.cardId,
        targets.filter((id): id is ObjectId => id !== undefined),
        activeSlots,
        colorsOf(ctx, perm),
      );
      const allTargets = [
        ...targets.filter((id): id is ObjectId => id !== undefined),
        ...Object.values(counted.countTargets).flat(),
      ];
      const description =
        (activated.ability.description ?? 'activated ability') +
        (modeLabel === undefined ? '' : ` [mode: ${modeLabel}]`);
      const id = `o-${s.nextObjectNum++}` as ObjectId;
      // Snapshot before paying: a sacrifice cost removes the permanent, and the stack entry
      // must still name its source (CR 608.2f — the ability resolves regardless).
      const stackEntry: EngineStackObject = {
        id,
        sourceId: perm.id,
        controllerId: player.id,
        kind: 'activatedAbility' as const,
        description: `${perm.name} — ${description}`,
        targets,
        ...(Object.keys(counted.countTargets).length > 0
          ? { countTargets: counted.countTargets }
          : {}),
        ...(Object.keys(counted.divisionAmounts).length > 0
          ? { divisionAmounts: counted.divisionAmounts }
          : {}),
        card: null,
        ability: announced,
        sourceColors: colorsOf(ctx, perm),
        sourceOracleId: perm.oracleId,
        sourceCardId: perm.cardId,
        isCommanderCast: false,
        triggerScope: {
          sourceCountersTotal: Object.values(perm.counters).reduce(
            (total, count) => total + count,
            0,
          ),
        },
        ...(payload.x !== undefined ? { announcedX: payload.x } : {}),
      };

      // Boast's activation cost reduction, and {X} announced as part of this activation (CR
      // 602.1b) — folded into the `mana` cost component before payment, the same treatment
      // `costSpell`'s X gets.
      const activationReduction = activationCostReductionFor(
        ctx,
        player.id,
        perm.oracleId,
        perm.cardId,
      );
      // The reduction applies once to the TOTAL mana cost with X announced (CR 601.2f), the way
      // `computePriorityOptions` priced it — spread across mana components, never applied twice.
      let reductionLeft = activationReduction.generic;
      const costsToPay = activated.costs.map((c) => {
        if (c.kind !== 'mana') return c;
        const announced = withX(c.cost, payload.x ?? 0);
        const reduced = subtractGeneric(announced, reductionLeft);
        reductionLeft -= announced.generic - reduced.generic;
        return { ...c, cost: reduced };
      });
      const paymentScope = yield* payActivationCosts(ctx, player, perm, costsToPay, payload.x ?? 0);
      if (paymentScope.stationPower !== undefined) {
        stackEntry.triggerScope = {
          ...stackEntry.triggerScope,
          stationPower: paymentScope.stationPower,
        };
      }
      // Recorded at ANNOUNCEMENT (CR 602.5f/606.3), not on resolution: the restriction is on
      // activating, so countering the ability does not give the activation back. A loyalty
      // ability is recorded even when `oncePerTurn` was left unset on its definition (e.g. a
      // hand-authored override) — CR 606.3's once-per-turn restriction comes from the loyalty
      // cost itself, not from that flag, so legal.ts's loyalty check must see it either way.
      if (activated.oncePerTurn === true || activated.costs.some((c) => c.kind === 'loyalty')) {
        perm.activationsThisTurn.push(payload.index);
      }
      if (activated.exhaust === true) {
        perm.exhaustedAbilities = [...(perm.exhaustedAbilities ?? []), payload.index];
      }
      s.stack.push(stackEntry);
      breakYieldsForStop(ctx, stackEntry);
      emit(
        ctx,
        'activateAbility',
        {
          player: player.id,
          source: perm.name,
          cardId: perm.cardId,
          description,
          targets: targets.filter((id): id is ObjectId => id !== undefined),
        },
        player.id,
      );
      debug(ctx, 'stack', `${player.id} activates ${perm.name} — ${description}`);
      queueWardTriggers(ctx, player.id, id, allTargets);
      queueBecomesTargetedTriggers(ctx, player.id, allTargets);
      return;
    }

    case 'companionToHand': {
      const companion = player.companion;
      if (companion === null || player.companionMovedToHand) {
        throw new Error('engine bug: companion action without a companion');
      }
      yield* payManaCost(ctx, player, { ...emptyCost(), generic: 3 });
      player.companionMovedToHand = true;
      const handObj: EngineCardObject = {
        ...companion,
        id: `o-${s.nextObjectNum++}` as ObjectId,
        zone: 'hand',
      };
      player.hand.push(handObj);
      player.companion = null;
      emit(ctx, 'companionToHand', { player: player.id, name: companion.name }, player.id);
      return;
    }
  }
}

export { makePermanent };
